                        query.orderBy(inspectionStandard.createdDate.desc());
                    }
                } else if (order.getProperty().equals("modifiedDate")) {
                    if (order.isAscending()) {
                        query.orderBy(inspectionStandard.modifiedDate.asc());
                    } else {
                        query.orderBy(inspectionStandard.modifiedDate.desc());
                    }
                }
            });
        } else {

            query.orderBy(inspectionStandard.id.desc());
        }


        long total = query.fetchCount();
        List<WeatherStandard> results = query
                .offset(pageable.getOffset())
                .limit(pageable.getPageSize())
                .fetch();

        return new PageImpl<>(results, pageable, total);
    }
}    private final JPAQueryFactory queryFactory;
    QOrder fAQ = QOrder.order;
    @Override
    public Page<Order> searchFAQs(String keyword, Pageable pageable) {
        BooleanBuilder builder = new BooleanBuilder();

        if (keyword != null && !keyword.isEmpty()) {

            builder.or(fAQ.question.like("%" + keyword + "%"))
                    .or(fAQ.answer.like("%" + keyword + "%"));
        }

        List<Order> results = queryFactory.selectFrom(fAQ)
                .where(builder)
                .offset(pageable.getOffset())
                .limit(pageable.getPageSize())
                .fetch();

        long total = queryFactory.select(fAQ.count())
                .from(fAQ)
                .where(builder)
                .fetchOne();

        return new PageImpl<>(results, pageable, total);
    }
}

    @Override
    public Page<WarehouseStorage> searchNotices(String keyword, Pageable pageable) {
        BooleanBuilder builder = new BooleanBuilder();


        if (StringUtils.hasText(keyword)) {
            builder.and(containsKeyword(keyword));
        }


        List<WarehouseStorage> results = queryFactory.selectFrom(notice)
                .where(builder)
                .orderBy(notice.createdDate.desc())
                .offset(pageable.getOffset())
                .limit(pageable.getPageSize())
                .fetch();


        Long total = queryFactory.select(notice.count())
                .from(notice)
                .where(builder)
                .fetchOne();

        return new PageImpl<>(results, pageable, Objects.requireNonNullElse(total, 0L));
    }

    @Override
    public Page<WarehouseStorage> searchNoticesByCategoryAndKeyword(WarehouseStorageCategory category, String keyword, Pageable pageable) {
        BooleanBuilder builder = new BooleanBuilder();


        if (category != null) {
            builder.and(notice.category.eq(category));
        }


        if (StringUtils.hasText(keyword)) {
            builder.and(containsKeyword(keyword));
        }


        List<WarehouseStorage> results = queryFactory.selectFrom(notice)
                .where(builder)
                .orderBy(notice.createdDate.desc())
                .offset(pageable.getOffset())
                .limit(pageable.getPageSize())
                .fetch();


        Long total = queryFactory.select(notice.count())
                .from(notice)
                .where(builder)
                .fetchOne();

        return new PageImpl<>(results, pageable, Objects.requireNonNullElse(total, 0L));
    }

